#!/usr/bin/env node
// Data export: writes docs/reference/game-data.md, a readable reference of every number the
// battle prototype actually uses, generated from index.html's data tables (and the latest
// battle-sim baseline). The design doc says what the game should be; this says what the
// prototype is. Never edit the generated file by hand.
//
//   node tools/data-export/export.js           regenerate docs/reference/game-data.md
//   node tools/data-export/export.js --check   exit 1 if the file is out of date (CI runs this)
//   node tools/data-export/export.js --json    print the tables as JSON instead
const fs = require('fs');
const path = require('path');
const { loadBattle, ROOT } = require('../lib/load-game');

const OUT = path.join(ROOT, 'docs/reference/game-data.md');
const BASELINE = path.join(ROOT, 'tools/battle-sim/baseline.json');
const B = loadBattle();
const D = n => B.get(n);
const ROSTER = D('ROSTER'), SKILLS = D('SKILLS'), ITEMS = D('ITEMS'), LIMIT = D('LIMIT'), AFFS = D('AFFS'), INSP = D('INSP');
const FOES = D('FOES'), ENCOUNTERS = D('ENCOUNTERS'), SCRIPTS = D('SCRIPTS'), STORY = D('STORY'), ROLE_DESC = D('ROLE_DESC');
const scriptInfo = D('scriptInfo'), lvScale = D('lvScale'), tickOf = D('tickOf'), SLOT = D('SLOT');

if (process.argv.includes('--json')) {
  const strip = o => JSON.parse(JSON.stringify(o)); // drops run/when functions
  console.log(JSON.stringify({ ROSTER, SKILLS, ITEMS, LIMIT, AFFS, INSP, FOES, ENCOUNTERS: strip(ENCOUNTERS), SCRIPTS: strip(SCRIPTS), STORY }, null, 1));
  process.exit(0);
}

const cell = v => String(v ?? '').replace(/\|/g, '\\|').replace(/\n/g, ' ');
const table = (head, rows) => [`| ${head.join(' | ')} |`, `| ${head.map(() => '---').join(' | ')} |`, ...rows.map(r => `| ${r.map(cell).join(' | ')} |`)].join('\n');
const owner = k => Object.values(ROSTER).find(r => r.skills.includes(k));
const base = fs.existsSync(BASELINE) ? JSON.parse(fs.readFileSync(BASELINE, 'utf8')) : {};
const pct = v => Math.round(v * 100) + '%';

const L = [];
L.push('# Game data reference');
L.push('');
L.push('<!-- Generated by tools/data-export/export.js from index.html and tools/battle-sim/baseline.json. Do not edit by hand: change the code, then run `node tools/data-export/export.js`. -->');
L.push('');
L.push('Every number the battle prototype (`index.html`) uses, as it stands. The [design doc](../design-doc.md) is the target; this is the current build. Where they disagree, `node tools/data-check/check.js` reports it, and [implementation status](../implementation-status.md) tracks it. Formulas are explained in [battle math](../systems/battle-math.md).');
L.push('');

L.push('## Party');
L.push('');
L.push(`Base stats at level 0. A character's HP, MP, ATK, DEF and MAG are scaled by ${'`0.6 + 0.04 × level`'}, where the level comes from the encounter (level 10: ×${lvScale(10).toFixed(2)}, level 20: ×${lvScale(20).toFixed(2)}, level 30: ×${lvScale(30).toFixed(2)}). Speed is not scaled. Tick speed is \`max(8, 30 − Speed)\`; an action of Delay *d* comes back after *d* × tick speed ticks, and one turn-order slot is ${SLOT} ticks.`);
L.push('');
L.push(table(['Character', 'Role', 'HP', 'MP', 'ATK', 'DEF', 'MAG', 'Speed', 'Tick', 'Skills', 'Limit Break'],
  Object.values(ROSTER).map(r => [r.name, r.role, r.hp, r.mp, r.atk, r.def, r.mag, r.agi, tickOf(r), r.skills.map(k => SKILLS[k].name).join(', '), r.lb])));
L.push('');
L.push(table(['Character', 'What only they do', 'Limit Break effect'], Object.entries(ROSTER).map(([id, r]) => [r.name, ROLE_DESC[id], LIMIT[id]])));
L.push('');

L.push('## Commands');
L.push('');
L.push('Attack, Defend and items are Delay 3; Limit Breaks are Delay 4. Out of MP, a spell costs 4 HP per missing MP.');
L.push('');
L.push(table(['Skill', 'Key', 'User', 'MP', 'Delay', 'Target', 'Effect'],
  Object.entries(SKILLS).map(([k, s]) => [s.name, k, (owner(k) || {}).name || '—', s.mp, s.delay, s.target, s.desc])));
L.push('');
L.push(table(['Item', 'Key', 'Target', 'Effect'], Object.entries(ITEMS).map(([k, i]) => [i.name, k, i.target, i.desc])));
L.push('');
L.push('Starting bag: 5 Potions, 3 Phoenix Downs, 3 Earplugs, unless the encounter sets its own.');
L.push('');

L.push('## Stress Check outcomes');
L.push('');
L.push(table(['Afflicted', 'Effect'], Object.entries(AFFS)));
L.push('');
L.push(table(['Inspired', 'Effect'], Object.entries(INSP)));
L.push('');

L.push('## Encounters');
L.push('');
L.push('Sim columns come from `tools/battle-sim/baseline.json`: the in-game Helper playing the default party. Turns are party commands in won fights.');
L.push('');
L.push(table(['Key', 'Encounter', 'Level', 'Danger', 'Party', 'Foes', 'Sim win', 'Sim turns', 'Sim Afflicted'],
  Object.entries(ENCOUNTERS).map(([k, e]) => {
    const b = base[k] && base[k].s;
    return [k, e.title, e.lv, e.hum, (e.party || []).map(p => ROSTER[p].name).join(', '), e.foes.map(f => FOES[f].name).join(', '),
      b ? pct(b.win) : '—', b ? b.winTurns.toFixed(0) : '—', b ? b.afflicted.toFixed(1) : '—'];
  })));
L.push('');
for (const [k, e] of Object.entries(ENCOUNTERS)) L.push(`- **${e.title}** (\`${k}\`). ${e.brief}`);
L.push('');

L.push('## Foes');
L.push('');
L.push(table(['Foe', 'Key', 'HP', 'ATK', 'DEF', 'MDEF', 'Speed', 'Tick', 'Crit', 'Part of', 'Ito source'],
  Object.entries(FOES).map(([k, f]) => [f.name, k, f.hp, f.atk, f.def, f.mdef, f.agi, tickOf(f), pct(f.crit || .1), f.parentKey ? FOES[f.parentKey].name : '—', STORY[k] || '—'])));
L.push('');

L.push('## Enemy scripts');
L.push('');
L.push('Each enemy runs a priority list: on planning, the first rule that holds picks the skill, and the plan shows in the turn order. Rules marked *reacts* are re-checked when the party acts. Rank is the skill\'s Delay.');
L.push('');
for (const [k, S] of Object.entries(SCRIPTS)) {
  const info = scriptInfo(k), sk = info.skills;
  L.push(`### ${FOES[k].name} (\`${k}\`)`);
  L.push('');
  if (S.phases) L.push('Phases: ' + S.phases.map(p => `**${p.id}** ${p.label}${p.enter ? ` (enters with ${sk[p.enter].name})` : ''}`).join('; ') + '.');
  if (S.parts) L.push('Parts: ' + S.parts.map(p => `${FOES[p.key].name}, re-forms ${p.respawn} turns after defeat${p.respawnP2 ? ` (${p.respawnP2} in phase 2)` : ''}${p.hpPct ? ` at ${pct(p.hpPct)} HP` : ''}`).join('; ') + '.');
  if (S.phases || S.parts) L.push('');
  info.tree.forEach((r, i) => {
    let line;
    if (r.roll) line = `${r.label}: roll ${r.roll.map(([p, s]) => `${sk[s].name} ${p}`).join(', ')}`;
    else if (r.always) line = `${r.label}: **${sk[r.always[0]].name}**`;
    else line = `If ${r.if.replace(/^(The|At|An|It|This|Another) /, w => w.toLowerCase())}${r.react ? ' *(reacts)*' : ''}: **${sk[r.then[0]].name}**${r.chance ? `, chance ${r.chance}` : ''}`;
    if (r.target) line += ` → ${r.target}`;
    L.push(`${i + 1}. ${line}`);
  });
  L.push('');
  L.push(table(['Skill', 'Rank', 'Tags', 'Target', 'Power', 'Effect'], Object.values(sk).map(s => [s.name, s.delay, s.tags.join(', '), s.target, s.power, s.effect])));
  if (info.notes.length) { L.push(''); info.notes.forEach(n => L.push(`- ${n}`)); }
  L.push('');
}

const md = L.join('\n').replace(/\n+$/, '\n');
if (process.argv.includes('--check')) {
  const cur = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  if (cur !== md) { console.error(`${path.relative(process.cwd(), OUT)} is out of date: run node tools/data-export/export.js`); process.exit(1); }
  console.log(`${path.relative(process.cwd(), OUT)} is up to date.`);
  process.exit(0);
}
fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, md);
console.log(`wrote ${path.relative(process.cwd(), OUT)} (${md.split('\n').length} lines)`);
process.exit(0);
